diff --git a/scripts/check-mcp-app-bundle.mjs b/scripts/check-mcp-app-bundle.mjs
index 1d186c97..878d37af 100644
--- a/scripts/check-mcp-app-bundle.mjs
+++ b/scripts/check-mcp-app-bundle.mjs
@@ -1,198 +1,198 @@
 /**
  * Post-build tripwire for MCP Apps.
  *
  * The current MCP Apps resource is a packed, self-contained HTML document so
  * it does not depend on cross-origin script execution inside a host sandbox.
  * We also keep a small external template for Lobu's own public app route. Its
  * stable assets use content-derived query versions for rolling deployments.
  */
 import { createHash } from "node:crypto";
 import { readdir, readFile, stat } from "node:fs/promises";

 const MAX_RESOURCE_RESPONSE_BYTES = 450_000;
 const APP_ORIGIN = "https://app.lobu.ai";
 const APP_BASE = `${APP_ORIGIN}/mcp-apps/interaction/`;
 const bundleUrl = new URL(
 	"../dist-mcp-apps/interaction/index.html",
 	import.meta.url,
 );
 const source = await readFile(bundleUrl, "utf8");
 const legacySource = await readFile(
 	new URL("../dist-mcp-apps/interaction/legacy-v2.html", import.meta.url),
 	"utf8",
 );
 const currentResourceSource = legacySource;
 const assetsUrl = new URL(
 	"../dist-mcp-apps/interaction/assets/",
 	import.meta.url,
 );
 const allAssetPaths = (await readdir(assetsUrl))
 	.map((name) => `assets/${name}`)
 	.sort();
 const renderedSource = source
 	.replace("<head>", `<head><base href="${APP_BASE}">`)
 	.replaceAll("__LOBU_MCP_APP_ORIGIN__", APP_ORIGIN);
 const sourceBytes = Buffer.byteLength(renderedSource, "utf8");
 const assetPaths = [
 	...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)(?:\?v=[^"]+)?"/g),
 ].map((match) => match[1]);
 const versionedAssetReferences = [
 	...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)\?v=([a-f0-9]{16})"/g),
 ].map((match) => ({ assetPath: match[1], version: match[2] }));
 const cssPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".css"));
 const scriptPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".js"));
 const resourceResponseBytes = Buffer.byteLength(
 	JSON.stringify({
 		jsonrpc: "2.0",
 		id: 1,
 		result: {
 			contents: [
 				{
-					uri: "ui://lobu/interaction/v10.html",
+					uri: "ui://lobu/interaction/v11.html",
 					mimeType: "text/html;profile=mcp-app",
 					text: currentResourceSource,
 					_meta: {
 						ui: {
 							csp: {
 								connectDomains: [],
 								resourceDomains: [],
 								frameDomains: [],
 								baseUriDomains: [],
 							},
 							permissions: { clipboardWrite: {} },
 							prefersBorder: true,
 						},
 					},
 				},
 			],
 		},
 	}),
 	"utf8",
 );
 const requiredStoredTemplateSelectors = [
 	".space-y-3",
 	".gap-4",
 	".pr-4",
 	".pt-6",
 	".grid-cols-\\[repeat\\(auto-fill\\,minmax\\(200px\\,1fr\\)\\)\\]",
 ];

 const errors = [];
 if (
 	!legacySource.includes('name="lobu-mcp-packing"') ||
 	!legacySource.includes("gzip-base64-self-contained") ||
 	!legacySource.includes("DecompressionStream") ||
 	!legacySource.includes("pako.ungzip")
 ) {
 	errors.push("self-contained MCP App template is incomplete");
 }
 if (
 	legacySource.includes("__LOBU_MCP_APP_ORIGIN__") ||
 	/(?:src|href)=["'](?:\.\/|\/)?assets\//.test(legacySource)
 ) {
 	errors.push("legacy v2 template still depends on external assets");
 }
 if (!source.includes("__LOBU_MCP_APP_ORIGIN__")) {
 	errors.push("dynamic MCP App origin placeholder is missing");
 }
 if (!renderedSource.includes(`<base href="${APP_BASE}">`)) {
 	errors.push("absolute MCP App asset base is missing");
 }
 if (!renderedSource.includes('http-equiv="Content-Security-Policy"')) {
 	errors.push("defense-in-depth Content Security Policy is missing");
 }
 if (source.includes("<script>") || source.includes("<style>")) {
 	errors.push("inline JS/CSS remains in the MCP App snapshot template");
 }
 if (
 	!/<script defer src="\.\/assets\/app\.js\?v=[a-f0-9]{16}"><\/script>/.test(
 		source,
 	) ||
 	/<script[^>]+type="module"/.test(source)
 ) {
 	errors.push(
 		"external MCP App template is not using one classic deferred script",
 	);
 }
 if (scriptPaths.length !== 1 || cssPaths.length !== 1) {
 	errors.push(
 		`expected one external JS and one external CSS asset; found ${scriptPaths.length} JS and ${cssPaths.length} CSS`,
 	);
 }
 const expectedAssetPaths = ["assets/app.css", "assets/app.js"];
 if (JSON.stringify(allAssetPaths) !== JSON.stringify(expectedAssetPaths)) {
 	errors.push(
 		`expected only stable MCP App assets ${expectedAssetPaths.join(", ")}; found ${allAssetPaths.join(", ")}`,
 	);
 }
 if (
 	JSON.stringify(
 		versionedAssetReferences.map(({ assetPath }) => assetPath).sort(),
 	) !== JSON.stringify(expectedAssetPaths)
 ) {
 	errors.push("stable MCP App asset URLs are missing content-derived versions");
 }
 if (resourceResponseBytes > MAX_RESOURCE_RESPONSE_BYTES) {
 	errors.push(
 		`resources/read JSON is ${resourceResponseBytes.toLocaleString()} bytes; budget is ${MAX_RESOURCE_RESPONSE_BYTES.toLocaleString()} bytes`,
 	);
 }

 let css = "";
 let javascript = "";
 for (const assetPath of allAssetPaths) {
 	const assetUrl = new URL(
 		`../dist-mcp-apps/interaction/${assetPath}`,
 		import.meta.url,
 	);
 	try {
 		await stat(assetUrl);
 		const asset = await readFile(assetUrl);
 		const expectedVersion = createHash("sha256")
 			.update(asset)
 			.digest("hex")
 			.slice(0, 16);
 		const reference = versionedAssetReferences.find(
 			(candidate) => candidate.assetPath === assetPath,
 		);
 		if (reference?.version !== expectedVersion) {
 			errors.push(`MCP App asset version does not match ${assetPath} contents`);
 		}
 		if (assetPath.endsWith(".css")) css += asset.toString("utf8");
 		if (assetPath.endsWith(".js")) javascript += asset.toString("utf8");
 	} catch {
 		errors.push(`referenced MCP App asset is missing: ${assetPath}`);
 	}
 }
 try {
 	// Compilation as a classic script rejects module-only syntax such as
 	// import.meta, top-level imports/exports, and top-level await.
 	new Function(javascript);
 } catch (error) {
 	errors.push(
 		`external MCP App JavaScript is not classic-script compatible: ${error}`,
 	);
 }
 if (
 	css.includes("/fonts/") ||
 	/url\(\s*(["']?)(?!data:|#)[^)]+\1\s*\)/i.test(css)
 ) {
 	errors.push("unexpected runtime URL remains in MCP App CSS");
 }
 for (const selector of requiredStoredTemplateSelectors) {
 	if (!css.includes(selector)) {
 		errors.push(
 			`stored json_template utility is missing from CSS: ${selector}`,
 		);
 	}
 }

 if (errors.length > 0) {
 	console.error("MCP App bundle check FAILED:\n");
 	for (const error of errors) console.error(`• ${error}`);
 	process.exitCode = 1;
 } else {
 	console.log(
-		`MCP App bundle check passed (${sourceBytes.toLocaleString()} external HTML bytes; ${resourceResponseBytes.toLocaleString()} v10 self-contained resources/read JSON bytes; ${Buffer.byteLength(legacySource).toLocaleString()} packed HTML bytes; classic content-versioned app.js/app.css).`,
+		`MCP App bundle check passed (${sourceBytes.toLocaleString()} external HTML bytes; ${resourceResponseBytes.toLocaleString()} v11 self-contained resources/read JSON bytes; ${Buffer.byteLength(legacySource).toLocaleString()} packed HTML bytes; classic content-versioned app.js/app.css).`,
 	);
 }
diff --git a/src/mcp-apps/_shared/openai-compat.ts b/src/mcp-apps/_shared/openai-compat.ts
index e769fdc1..f7b49103 100644
--- a/src/mcp-apps/_shared/openai-compat.ts
+++ b/src/mcp-apps/_shared/openai-compat.ts
@@ -1,107 +1,152 @@
 type UnknownRecord = Record<string, unknown>;

 const LOBU_VIEW_SNAPSHOT_KEY = "lobuViewSnapshot";
 const LOBU_VIEW_SNAPSHOT_VERSION = 1;

 export interface OpenAiCompatSnapshot<T> {
 	/** `undefined` means the host did not update this global. */
 	data: T | null | undefined;
 	/** `undefined` means the host did not update this global. */
 	approvalCapability: string | null | undefined;
 }

+function snapshotCapabilityFromMeta(meta: unknown): string | null {
+	if (!isStructuredObject(meta)) return null;
+	const token = meta["lobu/mcp-app-snapshot-capability"];
+	if (typeof token !== "string") return null;
+	const normalized = token.trim();
+	return normalized && normalized.length <= 512 ? normalized : null;
+}
+
 function isStructuredObject(value: unknown): value is UnknownRecord {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 export function approvalCapabilityFromMeta(meta: unknown): string | null {
 	if (!isStructuredObject(meta)) return null;
 	const token = meta["lobu/approval-capability"];
 	return typeof token === "string" && token.length <= 4_096 ? token : null;
 }

 function approvalCapabilityFromResult(result: unknown): string | null {
 	if (!isStructuredObject(result)) return null;
 	return approvalCapabilityFromMeta(result._meta);
 }

+function snapshotCapabilityFromResult(
+	result: unknown,
+): string | null | undefined {
+	if (!isStructuredObject(result) || !Object.hasOwn(result, "_meta"))
+		return undefined;
+	return snapshotCapabilityFromMeta(result._meta);
+}
+
+/** Read the opaque per-result restore key from ChatGPT compatibility globals. */
+export function snapshotCapabilityFromOpenAiGlobals(
+	globals: unknown,
+): string | null | undefined {
+	if (!isStructuredObject(globals)) return undefined;
+	const hasToolOutput = Object.hasOwn(globals, "toolOutput");
+	const hasFullToolResult =
+		hasToolOutput &&
+		isStructuredObject(globals.toolOutput) &&
+		Object.hasOwn(globals.toolOutput, "structuredContent");
+	const hasToolResponseMetadata = Object.hasOwn(
+		globals,
+		"toolResponseMetadata",
+	);
+	const metadata = isStructuredObject(globals.toolResponseMetadata)
+		? globals.toolResponseMetadata
+		: null;
+	if (hasToolResponseMetadata) {
+		return metadata
+			? (snapshotCapabilityFromResult(metadata.mcp_tool_result) ??
+					snapshotCapabilityFromResult(metadata.call_tool_result) ??
+					null)
+			: null;
+	}
+	return hasFullToolResult
+		? snapshotCapabilityFromResult(globals.toolOutput)
+		: undefined;
+}
+
 function dataFromToolOutput<T>(toolOutput: unknown): T | null {
 	if (!isStructuredObject(toolOutput)) return null;
 	if (Object.hasOwn(toolOutput, "structuredContent")) {
 		return isStructuredObject(toolOutput.structuredContent)
 			? (toolOutput.structuredContent as T)
 			: null;
 	}
 	return toolOutput as T;
 }

 function dataFromWidgetState<T>(widgetState: unknown): T | null | undefined {
 	if (!isStructuredObject(widgetState)) return undefined;
 	const privateContent = widgetState.privateContent;
 	if (!isStructuredObject(privateContent)) return undefined;
 	const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
 	if (!isStructuredObject(snapshot)) return undefined;
 	if (snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION) return undefined;
 	return snapshot.data === null
 		? null
 		: isStructuredObject(snapshot.data)
 			? (snapshot.data as T)
 			: undefined;
 }

 function displaySafeSnapshotData<T>(data: T | null): T | null {
 	if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
 	return {
 		...data,
 		actions: data.actions.filter(
 			(action) =>
 				!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
 		),
 	} as T;
 }

 /**
  * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
  * snapshot is a display-only reload fallback; a fresh tool result always wins.
  * Hidden result metadata is deliberately excluded.
  */
 export function persistOpenAiViewSnapshot<T>(
 	globals: unknown,
 	data: T | null,
 ): boolean {
 	if (!isStructuredObject(globals)) return false;
 	const setWidgetState = globals.setWidgetState;
 	if (typeof setWidgetState !== "function") return false;

 	const widgetState = isStructuredObject(globals.widgetState)
 		? globals.widgetState
 		: {};
 	const privateContent = isStructuredObject(widgetState.privateContent)
 		? widgetState.privateContent
 		: {};
 	const nextWidgetState = {
 		...widgetState,
 		privateContent: {
 			...privateContent,
 			[LOBU_VIEW_SNAPSHOT_KEY]: {
 				version: LOBU_VIEW_SNAPSHOT_VERSION,
 				data: displaySafeSnapshotData(data),
 			},
 		},
 	};

 	try {
 		const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
 		if (isStructuredObject(result) && typeof result.catch === "function") {
 			void Reflect.apply(result.catch, result, [() => {}]);
 		}
 		return true;
 	} catch {
 		return false;
 	}
 }

 /**
  * Read ChatGPT's compatibility globals without making them a dependency of the
  * portable MCP Apps bridge. ChatGPT restores these globals for historical
  * cards, including after the standard tool-result notification has already
