 44	const McpAppContext = createContext<McpAppApi<unknown>>({
 45		data: null,
 46		toolName: null,
 47		viewState: {},
 48		setViewState: () => {},
 49		callTool: async () => {},
 50		openLink: async () => {},
 51		lastResult: null,
 52		allowSpaHostedViews: false,
 53	});
